fn solve(queries: Vec<i8>) -> Vec<i8> {
    queries
        .into_iter()
        .map(|n| {
            // If n >= 4, we only need to add 0 if it's already even, or 1 if it's odd.
            // If n < 4, we need to add enough to reach 4.
            if n >= 4 {
                // n & 1 is 0 for even n, 1 for odd n
                n & 1
            } else {
                4 - n
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::solve;

    #[test]
    fn test_solve_examples() {
        // n >= 4, even => 0
        assert_eq!(solve(vec![4, 6, 8]), vec![0, 0, 0]);
        // n >= 4, odd => 1
        assert_eq!(solve(vec![5, 7, 9]), vec![1, 1, 1]);
        // n < 4
        assert_eq!(solve(vec![2, 3]), vec![2, 1]);
        // mixed cases
        assert_eq!(solve(vec![2, 4, 5, 3, 10, 7]), vec![2, 0, 1, 1, 0, 1]);
        // empty
        assert_eq!(solve(vec![]), Vec::<i8>::new());
    }
}